// CouponDuration says which of a subscription's invoices a coupon discounts.
type CouponDuration string

// Coupon durations.
const (
	// CouponOnce discounts only the first invoice created after the coupon is applied.
	CouponOnce CouponDuration = "once"
	// CouponRepeating discounts the invoices whose period starts less than DurationInMonths months after the coupon is applied.
	CouponRepeating CouponDuration = "repeating"
	// CouponForever discounts every invoice created after the coupon is applied.
	CouponForever CouponDuration = "forever"
)

// Coupon is a code that discounts an organization's subscriptions. It takes a percentage off (PercentOff) or an amount off
// (AmountOff, in Currency's minor unit), never both.
type Coupon struct {
	ID    string `json:"id"`
	OrgID string `json:"org_id"`
	Code  string `json:"code"`
	// PercentOff is the discount in percent, 1 to 100; nil for an amount coupon.
	PercentOff *int `json:"percent_off"`
	// AmountOff is the discount in minor units of Currency; nil for a percent coupon.
	AmountOff        *int64         `json:"amount_off"`
	Currency         money.Currency `json:"currency,omitempty"`
	Duration         CouponDuration `json:"duration"`
	DurationInMonths int            `json:"duration_in_months,omitempty"`
