func copyCoupon(c Coupon) Coupon {
	if c.PercentOff != nil {
		v := *c.PercentOff
		c.PercentOff = &v
	}
	if c.AmountOff != nil {
		v := *c.AmountOff
		c.AmountOff = &v
	}
	if c.RedeemBy != nil {
		t := *c.RedeemBy
		c.RedeemBy = &t
	}
