package subscriptions_test

import (
	"context"
	"errors"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/billing"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

// couponSub starts a monthly 20.00 USD subscription with no payment method (its invoices stay open) and returns it with the
// Acme plan's ID.
func couponSub(t *testing.T, e *apitest.Env, discountPercent int) store.Subscription {
	t.Helper()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1, DiscountPercent: discountPercent})
	if err != nil {
		t.Fatal(err)
	}
	return sub
}

func newCoupon(t *testing.T, e *apitest.Env, c store.Coupon) store.Coupon {
	t.Helper()
	c.OrgID = e.Acme.ID
	out, err := e.Store.CreateCoupon(c, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	return out
}

// renew moves the clock to the end of sub's current period and renews every due subscription; it returns the subscription.
func renew(t *testing.T, e *apitest.Env, sub store.Subscription) store.Subscription {
	t.Helper()
	e.Clock.Set(sub.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(context.Background()); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	return got
}

// lastInvoice returns the subscription's newest invoice and its discount.
func lastInvoice(e *apitest.Env, sub store.Subscription) (store.Invoice, int64) {
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	inv := invs[len(invs)-1]
	return inv, billing.Compute(inv).Discount
}

func TestForeverPercentCouponDiscountsEveryRenewal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := couponSub(t, e, 10)
	newCoupon(t, e, store.Coupon{Code: "QUARTER", PercentOff: intPtr(25), Duration: store.CouponForever})
	if _, err := e.Subs.ApplyCoupon(ctx, e.Acme.ID, sub.ID, "quarter"); err != nil {
		t.Fatal(err)
	}
	// The invoice created before the coupon keeps the subscription's own 10 percent.
	if inv, d := lastInvoice(e, sub); d != 200 || inv.Coupon != "" {
		t.Fatalf("first invoice = %+v discount %d", inv, d)
	}
	for range 3 {
		sub = renew(t, e, sub)
		inv, d := lastInvoice(e, sub)
		// The coupon takes the place of the subscription's 10 percent.
		if inv.Coupon != "QUARTER" || inv.DiscountPercent != 0 || d != 500 || billing.Compute(inv).Total != 1500 {
			t.Fatalf("renewal invoice = %+v discount %d", inv, d)
		}
	}
}

func TestOnceCouponDiscountsOnlyTheFirstInvoiceAfterIt(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := couponSub(t, e, 0)
	newCoupon(t, e, store.Coupon{Code: "FIVEOFF", AmountOff: int64Ptr(500), Currency: money.USD, Duration: store.CouponOnce})
	if _, err := e.Subs.ApplyCoupon(ctx, e.Acme.ID, sub.ID, "FIVEOFF"); err != nil {
		t.Fatal(err)
	}
	sub = renew(t, e, sub)
	if inv, d := lastInvoice(e, sub); d != 500 || inv.Coupon != "FIVEOFF" {
		t.Fatalf("first renewal = %+v discount %d", inv, d)
	}
	sub = renew(t, e, sub)
	if inv, d := lastInvoice(e, sub); d != 0 || inv.Coupon != "" || billing.Compute(inv).Total != 2000 {
		t.Fatalf("second renewal = %+v discount %d", inv, d)
	}
}

func TestRepeatingCouponStopsAfterItsMonths(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := couponSub(t, e, 0)
	newCoupon(t, e, store.Coupon{Code: "HALFTWO", PercentOff: intPtr(50), Duration: store.CouponRepeating, DurationInMonths: 2})
	if _, err := e.Subs.ApplyCoupon(ctx, e.Acme.ID, sub.ID, "HALFTWO"); err != nil {
		t.Fatal(err)
	}
	// Periods starting in the first two months after the redemption are discounted; the third is not.
	want := []int64{1000, 0}
	for i, d := range want {
		sub = renew(t, e, sub)
		if _, got := lastInvoice(e, sub); got != d {
			t.Fatalf("renewal %d: discount %d, want %d", i+1, got, d)
		}
	}
}

func TestCouponAppliedMidPeriodWaitsForTheNextInvoice(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := couponSub(t, e, 0)
	e.Clock.Advance(10 * 24 * time.Hour)
	newCoupon(t, e, store.Coupon{Code: "LATER", PercentOff: intPtr(20), Duration: store.CouponOnce})
	if _, err := e.Subs.ApplyCoupon(ctx, e.Acme.ID, sub.ID, "LATER"); err != nil {
		t.Fatal(err)
	}
	// Nothing is due yet, so the coupon waits for the period's end.
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 0 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	sub = renew(t, e, sub)
	if inv, d := lastInvoice(e, sub); d != 400 || inv.Coupon != "LATER" {
		t.Fatalf("renewal = %+v discount %d", inv, d)
	}
}

func TestPlanChangeKeepsTheAmountCouponsCurrency(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := couponSub(t, e, 0)
	newCoupon(t, e, store.Coupon{Code: "USDOFF", AmountOff: int64Ptr(500), Currency: money.USD, Duration: store.CouponForever})
	if _, err := e.Subs.ApplyCoupon(ctx, e.Acme.ID, sub.ID, "USDOFF"); err != nil {
		t.Fatal(err)
	}
	eur := e.CreatePlan(e.Acme, "Team EUR", "EUR", "18.00")
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &eur.ID}); !errors.Is(err, store.ErrCurrencyMismatch) {
		t.Fatalf("plan change to EUR: %v", err)
	}
}

func TestAmountCouponNeverTakesMoreThanTheSubtotal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := couponSub(t, e, 0)
	newCoupon(t, e, store.Coupon{Code: "BIGOFF", AmountOff: int64Ptr(5000), Currency: money.USD, Duration: store.CouponForever})
	if _, err := e.Subs.ApplyCoupon(ctx, e.Acme.ID, sub.ID, "BIGOFF"); err != nil {
		t.Fatal(err)
	}
	sub = renew(t, e, sub)
	inv, _ := lastInvoice(e, sub)
	if tot := billing.Compute(inv); tot.Discount != 2000 || tot.Total != 0 {
		t.Fatalf("totals = %+v", tot)
	}
}

func intPtr(v int) *int       { return &v }
func int64Ptr(v int64) *int64 { return &v }

